sys_script_include.script:
var TBA_TravelReferenceUtils = Class.create();
TBA_TravelReferenceUtils.prototype = {
    initialize: function() {},


    // FUNCTION 1: Filter to show only active Travel Buddies on any table
    getActiveBuddies: function() {
        var queryString = 'x_travel_buddy_app_u_istravelbuddy=true^active=true';
        return queryString;
    },


    // FUNCTION 2: on [Trip Request Table] Filter Itineraries Package based on the selected Destination
    getItinerariesForCity: function(cityId) {
        // If the user hasn't selected a destination yet, return nothing
        if (!cityId) {
            return 'sys_id=0';
        }
        var queryString = 'u_main_location=' + cityId;
        return queryString;
    },

	/* FUNCTION: Filter to show ONLY available Buddies for specific dates
    // ==========================================
    getAvailableBuddies: function(tripStart, tripEnd) {

        // 1. If the user hasn't picked dates yet, show nobody (forces them to pick dates first)
        if (!tripStart || !tripEnd) {
            return 'sys_id=0';
        }

        var busyBuddyIds = [];

        // 2. Search the Master Schedule table for any "Busy" blocks that overlap our requested dates
        var spanCheck = new GlideRecord('cmn_schedule_span');
        spanCheck.addQuery('show_as', 'Busy'); 

        // The Overlap Math:
        spanCheck.addQuery('start_date_time', '<', tripEnd);
        spanCheck.addQuery('end_date_time', '>', tripStart);
        spanCheck.query();

        // 3. Collect the IDs of every Buddy who has a busy block during this time
        while (spanCheck.next()) {
            // We dot-walk from the span -> to the master schedule -> to the user profile
            var buddyId = spanCheck.schedule.u_guide_profile.toString();
            if (buddyId && busyBuddyIds.indexOf(buddyId) === -1) {
                busyBuddyIds.push(buddyId);
            }
        }

        // 4. Build the final query: "Show me active Travel Buddies who are NOT in the Busy list"
        var finalQuery = 'u_is_travel_buddy=true^active=true';

        if (busyBuddyIds.length > 0) {
            finalQuery += '^sys_idNOT IN' + busyBuddyIds.join(',');
        }

        return finalQuery;
    },*/

    type: 'TBA_TravelReferenceUtils'
};
